//! Desktop executable. Mobile applications mount the same library root through
//! the platform runner generated by `nsh run` / `nsh package`.

#![cfg_attr(target_os = "windows", windows_subsystem = "windows")]

#[cfg(target_os = "linux")]
use nsh_platform_linux as platform;
#[cfg(target_os = "macos")]
use nsh_platform_macos as platform;
#[cfg(target_os = "windows")]
use nsh_platform_windows as platform;

#[cfg(any(target_os = "linux", target_os = "macos", target_os = "windows"))]
fn main() -> std::process::ExitCode {
    use std::process::Termination;
    if std::env::args()
        .skip(1)
        .any(|arg| arg == "--version" || arg == "-V")
    {
        println!("sysmon {}", env!("CARGO_PKG_VERSION"));
        return std::process::ExitCode::SUCCESS;
    }
    env_logger::init();
    platform::run_app(
        platform::AppSource::Rust(platform::Root::of::<sysmon::App>()),
        platform::AppOptions {
            title: "sysmon".to_owned(),
            appearance: nsh_core::platform::Appearance::Dark,
            app_id: "dev.sysmon.app".to_owned(),
            size: (1120, 760),
            ..Default::default()
        },
    )
    .report()
}

#[cfg(not(any(target_os = "linux", target_os = "macos", target_os = "windows")))]
compile_error!(
    "The desktop binary is only for macOS, Windows and Linux. For iOS/Android use `nsh run --target ios` / `nsh run --target android`, which generate a native runner for this crate's App root."
);
